import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: adapters","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_ext_eval/adapters.md","filePath":"api/host/handl_plugin_ext_eval/adapters.md"}`),a={name:`api/host/handl_plugin_ext_eval/adapters.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_plugin_ext_eval &gt; adapters</strong></p><h1 id="module-adapters" tabindex="-1">Module: adapters <a class="header-anchor" href="#module-adapters" aria-label="Permalink to “Module: adapters”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Structs</strong></p><ul><li><a href="#asyncfn"><code>AsyncFn</code></a> - An [<code>AsyncFunction</code>] backed by a closure that returns a boxed future.</li><li><a href="#genericfunction"><code>GenericFunction</code></a> - A [<code>Function</code>] backed by a closure.</li><li><a href="#lazyfunction"><code>LazyFunction</code></a> - A [<code>Function</code>] that constructs its inner function on first call and caches</li></ul><p><strong>Type Aliases</strong></p><ul><li><a href="#evalfuture"><code>EvalFuture</code></a> - A boxed eval future: single-threaded (no <code>Send</code> bound), borrowing its inputs.</li></ul><hr><h2 id="handl-plugin-ext-eval-adapters-asyncfn" tabindex="-1">handl_plugin_ext_eval::adapters::AsyncFn <a class="header-anchor" href="#handl-plugin-ext-eval-adapters-asyncfn" aria-label="Permalink to “handl_plugin_ext_eval::adapters::AsyncFn”">​</a></h2><p><em>Struct</em></p><p>An [<code>AsyncFunction</code>] backed by a closure that returns a boxed future.</p><p>The closure has a higher-ranked signature: <code>for&lt;&#39;a&gt; Fn(&amp;&#39;a [Value], &amp;&#39;a mut EvalContext) -&gt; EvalFuture&lt;&#39;a&gt;</code>, matching [<code>AsyncFunction::call_async</code>]. This is the ADR 0040 replacement for <code>plugin-vm-common</code>&#39;s <code>FnAsync</code> adapter.</p><p><code>AsyncFn</code> also implements [<code>Function</code>]: the sync [<code>Function::call</code>] returns an [<code>EvalError::Other</code>] indicating the function is async-only, and [<code>Function::as_async</code>] returns <code>Some(self)</code> so that [<code>EvalContext::call_function_async</code>] dispatches through the async path. This lets an <code>AsyncFn</code> be registered in a <a href="./handl_platform::Module.html"><code>Module</code></a> (which stores <code>Arc&lt;dyn Function&gt;</code>) and reached via async lookup.</p><h1 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h1><div class="language-ignore"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_plugin_ext_eval::AsyncFn;</span></span>
<span class="line"><span>use handl_platform::{AsyncFunction, EvalContext, EvalError};</span></span>
<span class="line"><span>use serde_json::{Value, json};</span></span>
<span class="line"><span>use std::future::ready;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let fetch = AsyncFn::new(&quot;fetch&quot;, |args, _ctx| {</span></span>
<span class="line"><span>    Box::pin(ready(Ok(json!(format!(&quot;fetched:{}&quot;, args[0].as_str().unwrap())))))</span></span>
<span class="line"><span>});</span></span></code></pre></div><p><strong>Generic Parameters:</strong></p><ul><li>F</li></ul><p><strong>Fields:</strong></p><ul><li><code>name: String</code></li><li><code>handler: F</code></li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new&lt;impl Into&lt;String&gt;&gt;(name: impl Trait, handler: F) -&gt; Self</code> - Create a new async function with the given name and handler closure.</li><li><code>fn name(self: &amp;Self) -&gt; &amp;str</code> - The function&#39;s name.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>AsyncFunction</strong><ul><li><code>fn call_async&lt;&#39;a&gt;(self: &amp;&#39;a Self, args: &amp;&#39;a [Value], ctx: &amp;&#39;a mut EvalContext) -&gt; Pin&lt;Box&lt;dyn Future&gt;&gt;</code></li></ul></li><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, _args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li><li><code>fn as_async(self: &amp;Self) -&gt; Option&lt;&amp;dyn AsyncFunction&gt;</code></li></ul></li></ul><h2 id="handl-plugin-ext-eval-adapters-evalfuture" tabindex="-1">handl_plugin_ext_eval::adapters::EvalFuture <a class="header-anchor" href="#handl-plugin-ext-eval-adapters-evalfuture" aria-label="Permalink to “handl_plugin_ext_eval::adapters::EvalFuture”">​</a></h2><p><em>Type Alias</em>: <code>std::pin::Pin&lt;Box&lt;dyn Future&gt;&gt;</code></p><p>A boxed eval future: single-threaded (no <code>Send</code> bound), borrowing its inputs.</p><h2 id="handl-plugin-ext-eval-adapters-genericfunction" tabindex="-1">handl_plugin_ext_eval::adapters::GenericFunction <a class="header-anchor" href="#handl-plugin-ext-eval-adapters-genericfunction" aria-label="Permalink to “handl_plugin_ext_eval::adapters::GenericFunction”">​</a></h2><p><em>Struct</em></p><p>A [<code>Function</code>] backed by a closure.</p><p>The closure receives the argument slice and a mutable [<code>EvalContext</code>], matching the [<code>Function::call</code>] signature. This lets library and host code define inline functions without writing a one-off struct. It is the public-utility analogue of <code>handl-test-utils</code>&#39;s <code>MockFunction</code> (ported from <code>plugin-vm-common</code>&#39;s <code>FnGeneric</code> / <code>FnFunction</code>).</p><h1 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to “Example”">​</a></h1><div class="language-ignore"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_plugin_ext_eval::GenericFunction;</span></span>
<span class="line"><span>use handl_platform::Function;</span></span>
<span class="line"><span>use serde_json::{Value, json};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let add = GenericFunction::new(&quot;add&quot;, |args, _ctx| {</span></span>
<span class="line"><span>    let a = args[0].as_i64().unwrap();</span></span>
<span class="line"><span>    let b = args[1].as_i64().unwrap();</span></span>
<span class="line"><span>    Ok(json!(a + b))</span></span>
<span class="line"><span>});</span></span></code></pre></div><p><strong>Fields:</strong></p><ul><li><code>name: String</code></li><li><code>handler: Box&lt;dyn Fn&gt;</code></li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new&lt;impl Into&lt;String&gt;, impl Fn(&amp;[Value], &amp;mut EvalContext) -&gt; Result&lt;Value, EvalError&gt; + Send + Sync + &#39;static&gt;(name: impl Trait, handler: impl Trait) -&gt; Self</code> - Create a new generic function with the given name and handler closure.</li><li><code>fn name(self: &amp;Self) -&gt; &amp;str</code> - The function&#39;s name.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul><h2 id="handl-plugin-ext-eval-adapters-lazyfunction" tabindex="-1">handl_plugin_ext_eval::adapters::LazyFunction <a class="header-anchor" href="#handl-plugin-ext-eval-adapters-lazyfunction" aria-label="Permalink to “handl_plugin_ext_eval::adapters::LazyFunction”">​</a></h2><p><em>Struct</em></p><p>A [<code>Function</code>] that constructs its inner function on first call and caches it for subsequent calls.</p><p>This is the ADR 0040 replacement for <code>plugin-vm-common</code>&#39;s <code>FnLazy</code> adapter, reinterpreted as a lazy-initialization wrapper (the new system&#39;s eval rules handle argument evaluation, so the old &quot;receives unevaluated args&quot; semantics are no longer needed at the <code>Function</code> level). The init closure runs at most once; afterwards every call delegates to the cached inner [<code>Function</code>].</p><p>Useful for functions that are expensive to construct (e.g. ones that build a lookup table or open a resource on first use) but cheap to invoke.</p><h1 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to “Example”">​</a></h1><div class="language-ignore"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_plugin_ext_eval::{GenericFunction, LazyFunction};</span></span>
<span class="line"><span>use handl_platform::Function;</span></span>
<span class="line"><span>use serde_json::{Value, json};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let lazy = LazyFunction::new(&quot;expensive&quot;, || {</span></span>
<span class="line"><span>    Box::new(GenericFunction::new(&quot;expensive&quot;, |args, _ctx| {</span></span>
<span class="line"><span>        Ok(json!(args[0]))</span></span>
<span class="line"><span>    }))</span></span>
<span class="line"><span>});</span></span></code></pre></div><p><strong>Fields:</strong></p><ul><li><code>name: String</code></li><li><code>init: std::sync::Mutex&lt;Option&lt;Box&lt;dyn FnOnce&gt;&gt;&gt;</code></li><li><code>cached: std::sync::Mutex&lt;Option&lt;Box&lt;dyn Function&gt;&gt;&gt;</code></li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new&lt;impl Into&lt;String&gt;, impl FnOnce() -&gt; Box&lt;dyn Function + Send + Sync&gt; + Send + Sync + &#39;static&gt;(name: impl Trait, init: impl Trait) -&gt; Self</code> - Create a new lazy function.</li><li><code>fn name(self: &amp;Self) -&gt; &amp;str</code> - The function&#39;s name.</li><li><code>fn is_initialized(self: &amp;Self) -&gt; bool</code> - Returns <code>true</code> if the inner function has been initialized.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul>`,51)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};